function icon(name,size=18){const paths={spark:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Z"/><path d="m19 14 .9 2.1L22 17l-2.1.9L19 20l-.9-2.1L16 17l2.1-.9L19 14Z"/>',code:'<path d="m8 17-5-5 5-5M16 7l5 5-5 5M14 4l-4 16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',arrow:'<path d="M7 17 17 7M7 7h10v10"/>',plus:'<path d="M12 5v14m-7-7h14"/>',send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>',paperclip:'<path d="m21.4 11.1-8.5 8.5a6 6 0 0 1-8.5-8.5l9.2-9.2a4 4 0 0 1 5.7 5.7L10 17a2 2 0 0 1-2.8-2.8l8.5-8.5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',trash:'<path d="M3 6h18m-2 0-1 14H6L5 6m3 0V4h8v2m-7 4v6m4-6v6"/>',play:'<path d="m7 4 14 8-14 8V4Z"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4m4-5 5 5 5-5m-5 5V3"/>',close:'<path d="m18 6-12 12M6 6l12 12"/>',chevron:'<path d="m9 18 6-6-6-6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.spark}</svg>`}
function logo(){return `<span class="brand-mark">${icon("code",18)}</span><span class="brand-name">compyde<span class="brand-dot">.</span></span>`}
function header(){return `<header class="topbar"><button class="brand" data-page="home" aria-label="COMPYDE home">${logo()}</button><nav class="main-nav" aria-label="Main navigation"><button class="nav-link ${state.page==='home'?'active':''}" data-page="home">Home</button><button class="nav-link ${state.page==='compiler'?'active':''}" data-page="compiler">Compiler Hub</button><button class="nav-link ${state.page==='assistant'?'active':''}" data-page="assistant">Smart Assistant</button><button class="nav-link" data-about>About</button></nav><div class="top-actions"><span class="mode-indicator"><i></i>${state.mode==='local'?'Local AI':'Cloud AI'}</span><button class="mobile-menu icon-btn" data-mobile-menu aria-label="Open navigation">${icon("menu")}</button></div></header>`}
function home(){return `<main class="home-page"><section class="hero"><div class="hero-kicker"><span class="kicker-dot"></span> YOUR SPACE TO THINK IN CODE</div><h1>Your complete<br><span>programming workspace.</span></h1><p class="hero-copy">Learn programming, write code, solve problems and get AI-powered help — all in one place.</p><div class="hero-composer"><div id="attachment-strip"></div><textarea id="hero-prompt" rows="2" placeholder="Ask anything about code…" aria-label="Ask COMPYDE a programming question"></textarea><div class="composer-bottom"><div class="composer-tools"><button class="icon-btn" data-upload title="Attach image or PDF">${icon("paperclip")}</button><span class="tiny-hint">Image or PDF</span><div class="mode-switch"><button class="${state.mode==='local'?'selected':''}" data-mode="local">Local</button><button class="${state.mode==='cloud'?'selected':''}" data-mode="cloud">Cloud</button></div></div><button class="send-btn" data-hero-send>Ask COMPYDE ${icon("arrow",16)}</button></div><input hidden type="file" id="file-input" accept="image/jpeg,image/png,image/webp,application/pdf"></div><div class="prompt-suggestions"><span>Try asking</span>${["Explain Python loops","Generate a C++ program","Debug my Java code","Explain this SQL query"].map(x=>`<button data-suggest="${esc(x)}">${esc(x)} ${icon("arrow",12)}</button>`).join("")}</div></section><section class="product-cards"><button class="product-card compiler-card" data-page="compiler"><div class="card-top"><span class="card-icon green">${icon("code",21)}</span><span class="card-arrow">${icon("arrow",17)}</span></div><div class="card-label">01 / WRITE & RUN</div><h2>Compiler Hub</h2><p>Write, run, test and debug code in one focused workspace.</p><div class="language-pills"><span>Python</span><span>JavaScript</span><span>SQL</span><span>+ more</span></div></button><button class="product-card assistant-card" data-page="assistant"><div class="card-top"><span class="card-icon violet">${icon("spark",21)}</span><span class="card-arrow">${icon("arrow",17)}</span></div><div class="card-label">02 / ASK & LEARN</div><h2>Smart Assistant</h2><p>Learn programming and solve technical questions with AI.</p><div class="language-pills"><span>Cloud AI</span><span>On-device AI</span><span>Image & PDF</span></div></button></section><section class="how-section" id="about"><div class="section-eyebrow">A BETTER WAY TO BUILD SKILLS</div><div class="how-head"><h2>Everything clicks<br>when it’s all in one place.</h2><p>Go from a question to a working solution, at your own pace. COMPYDE keeps your tools close and your learning in flow.</p></div><div class="steps"><article><span>01</span><h3>Ask a question</h3><p>Start with a concept, an error, or a file you want to understand.</p></article><article><span>02</span><h3>Work it through</h3><p>Get a clear explanation or try your solution in the Compiler Hub.</p></article><article><span>03</span><h3>Make it yours</h3><p>Iterate, learn from the result and keep your history on your device.</p></article></div></section><section class="platform-note"><div><span class="section-eyebrow">BUILT FOR THE WAY YOU LEARN</span><h2>Your device.<br>Your choice of AI.</h2></div><div class="mode-notes"><article><span class="note-symbol">◉</span><div><h3>Local AI</h3><p>Run an open model in your browser with WebGPU. Your prompts stay on your device. The first model load downloads files from the model host.</p></div></article><article><span class="note-symbol cloud-symbol">✳</span><div><h3>Cloud AI</h3><p>Call Gemini directly from your browser with your own API key. The key stays in memory for this tab only; browser-based keys can be inspected, so restrict the key to the Gemini API.</p></div></article><small>Model downloads can be large. Local AI requires a compatible browser and WebGPU device.</small></div></section><footer class="footer"><button class="brand" data-page="home">${logo()}</button><span>Code. Learn. Solve.</span><span>Made for curious minds.</span></footer></main>`}
function assistant(){return `<main class="assistant-layout ${state.sidebar?'':'sidebar-hidden'}"><aside class="chat-sidebar"><div class="sidebar-head"><span class="side-title">WORKSPACE</span><button class="icon-btn" data-collapse title="Collapse sidebar">${icon("menu",17)}</button></div><button class="new-chat" data-new-chat>${icon("plus",17)} New chat <kbd>⌘ K</kbd></button><label class="search-box">⌕<input id="search-chats" placeholder="Search chats" aria-label="Search conversations"></label><div class="history-label">RECENTS</div><div id="history-list" class="history-list"></div><div class="sidebar-bottom"><button data-export-chats>↓ Export conversations</button><button data-delete-all>${icon("trash",15)} Clear all history</button><p>Chats stay in this browser.<br><a href="#about" data-page="home">Learn about privacy</a></p></div></aside><section class="chat-area"><div class="chat-toolbar"><button class="icon-btn sidebar-toggle" data-collapse aria-label="Toggle sidebar">${icon("menu",18)}</button><div class="workspace-title">Smart Assistant <span>${icon("chevron",13)}</span></div><div class="toolbar-actions"><div class="mode-picker"><button data-mode-menu><span class="mode-dot ${state.mode}"></span>${state.mode==='local'?'Local AI':'Cloud AI'} <span class="select-chevron">⌄</span></button><div class="mode-dropdown" hidden><button data-mode="local"><b>Local AI</b><small>On-device · prompts stay here</small></button><button data-mode="cloud"><b>Cloud AI</b><small>Gemini · needs your API key</small></button></div></div><button class="icon-btn" data-models title="Model settings">⚙</button></div></div><div id="chat-scroll" class="chat-scroll"><div id="chat-content"></div></div><div class="chat-compose-wrap"><div class="capability-line"><span>${state.mode==='local'?'Private inference on this device':'Gemini API · direct from your browser'}</span><button data-models>${state.mode==='local'?models.find(m=>m.id===state.model)?.name||'Choose model':'Configure Gemini'}</button></div><div id="attachment-strip"></div><div class="chat-composer"><textarea id="chat-input" rows="1" placeholder="Message COMPYDE…" aria-label="Message Smart Assistant"></textarea><div class="compose-footer"><div class="compose-left"><button class="icon-btn" data-upload title="Attach image or PDF">${icon("paperclip",17)}</button><span class="attach-label">Attach a file</span></div><button class="send-round" data-chat-send aria-label="Send message">${icon("send",17)}</button></div></div><p class="privacy-caption">${state.mode==='local'?'Local mode never sends your prompt to Gemini.':'Your prompts and attachments go directly to Google Gemini.'} <span>AI can make mistakes.</span></p></div><input hidden type="file" id="file-input" accept="image/jpeg,image/png,image/webp,application/pdf"></section><dialog id="settings-dialog" class="settings-dialog"></dialog></main>`}
function compiler(){return `<main class="compiler-page"><div class="compiler-heading"><div><span class="section-eyebrow">YOUR CODING WORKSPACE</span><h1>Compiler Hub</h1><p>Write, run and experiment. Your code runs in your browser.</p></div><button class="outline-btn" data-send-assistant>${icon("spark",16)} Ask Assistant</button></div><section class="editor-card"><div class="editor-toolbar"><div class="editor-left"><span class="live-dot"></span><select id="language-select" aria-label="Select programming language"><option value="javascript" ${state.language==='javascript'?'selected':''}>JavaScript</option><option value="python" ${state.language==='python'?'selected':''}>Python</option><option value="sql" ${state.language==='sql'?'selected':''}>SQL</option><option value="html" ${state.language==='html'?'selected':''}>HTML + CSS</option><option value="c" ${state.language==='c'?'selected':''}>C · online</option><option value="cpp" ${state.language==='cpp'?'selected':''}>C++ · online</option><option value="java" ${state.language==='java'?'selected':''}>Java · online</option></select><select id="sample-select" aria-label="Choose a sample"><option value="">Sample programs</option><option value="hello">Hello world</option><option value="factorial">Factorial</option><option value="fibonacci">Fibonacci</option></select></div><div class="editor-actions"><button data-copy-code title="Copy code">${icon("copy",15)}</button><button data-download-code title="Download code">${icon("download",15)}</button><button data-reset-code>Reset</button><button class="run-btn" data-run>${icon("play",14)} Run</button></div></div><div id="editor-host" class="editor-host"><textarea id="code-editor" spellcheck="false" aria-label="Code editor"></textarea></div><label id="stdin-panel" class="stdin-panel" ${["c","cpp","java"].includes(state.language)?"":"hidden"}><span>PROGRAM INPUT (OPTIONAL)</span><textarea id="compiler-stdin" rows="2" placeholder="Input passed to scanf, cin or Scanner…"></textarea></label><div class="output-head"><span>${state.language==='html'?'PREVIEW':'OUTPUT'}</span><button data-clear-output>Clear output</button></div><pre id="compiler-output" class="compiler-output">Ready when you are. Choose a language and run your code.</pre></section><div class="compiler-footnote">${icon("spark",15)} JavaScript, Python, SQL and HTML run here. C, C++ and Java code and input are sent to the public <a href="https://wandbox.org/" target="_blank" rel="noreferrer">Wandbox</a> service over HTTPS for compilation; it may log submissions, rate-limit requests or be unavailable.</div></main>`}
function render(){const app=$("#app");app.innerHTML=header()+(state.page==='home'?home():state.page==='assistant'?assistant():compiler());bind();if(state.page==='assistant'){renderHistory();renderMessages();enhanceAssistantActions();renderAttachments();$('[data-export-chats]')?.addEventListener('click',exportChats);updateSendButton()}if(state.page==='compiler'){setupEditor();$('#language-select')?.addEventListener('change',()=>{$('.output-head span').textContent=state.language==='html'?'PREVIEW':'OUTPUT'})}}
function navigate(page){state.page=page;history.replaceState({},"",page==='home'?'#home':`#${page}`);render();window.scrollTo(0,0)}
function bind(){document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>navigate(b.dataset.page));$("[data-about]")?.addEventListener("click",()=>{if(state.page!=='home')navigate('home');setTimeout(()=>$("#about")?.scrollIntoView({behavior:'smooth'}),20)});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$("[data-mode-menu]")?.addEventListener("click",()=>{$(".mode-dropdown").hidden=!$(".mode-dropdown").hidden});document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>$('[type=file]')?.click());$("#file-input")?.addEventListener("change",handleFiles);document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{navigate('assistant');setTimeout(()=>{const i=$('#chat-input');if(i){i.value=b.dataset.suggest;i.focus()}},20)});$("[data-hero-send]")?.addEventListener("click",()=>{const prompt=$('#hero-prompt').value.trim();if(prompt){navigate('assistant');sendPrompt(prompt)}});$("#hero-prompt")?.addEventListener("keydown",e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$("[data-hero-send]").click()}});$("[data-new-chat]")?.addEventListener("click",newChat);document.querySelectorAll('[data-collapse]').forEach(b=>b.onclick=()=>{state.sidebar=!state.sidebar;$('.assistant-layout')?.classList.toggle('sidebar-hidden',!state.sidebar)});$("[data-chat-send]")?.addEventListener("click",()=>{if(state.generationController)stopGeneration();else sendPrompt($('#chat-input').value.trim())});$("#chat-input")?.addEventListener("keydown",e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(!state.generationController)sendPrompt(e.currentTarget.value.trim())}});$("[data-delete-all]")?.addEventListener("click",clearAll);$("#search-chats")?.addEventListener("input",renderHistory);if($("[data-run]"))$("[data-run]").onclick=runCode;if($("[data-clear-output]"))$("[data-clear-output]").onclick=()=>{restoreCompilerOutput().textContent='Output cleared.'};$("[data-reset-code]")?.addEventListener("click",()=>{setEditorCode(starter[state.language])});$("[data-copy-code]")?.addEventListener("click",()=>navigator.clipboard?.writeText(getCode()));$("[data-download-code]")?.addEventListener("click",downloadCode);$("[data-send-assistant]")?.addEventListener("click",()=>{const code=getCode();navigate('assistant');setTimeout(()=>{const i=$('#chat-input');if(i)i.value=`Please explain this ${state.language} code:\n\n\`\`\`\n${code}\n\`\`\``},20)});$("#language-select")?.addEventListener("change",e=>{state.language=e.target.value;localStorage.setItem("compyde-language",state.language);if(state.editor)state.editor.dispatch({effects:[languageSlot.reconfigure(editorLanguageExtension()),completionSlot.reconfigure(editorCompletionExtension())]});setEditorCode(starter[state.language]);$("#sample-select").value="";$("#stdin-panel").hidden=!["c","cpp","java"].includes(state.language);restoreCompilerOutput().textContent="Ready when you are. Run your code to see the output."});$("#sample-select")?.addEventListener("change",e=>{if(e.target.value){const code=samples[e.target.value]?.[state.language];if(code){setEditorCode(code)}else restoreCompilerOutput().textContent='That sample is not available for this language.'}});$("[data-mobile-menu]")?.addEventListener("click",()=>$('.main-nav').classList.toggle('mobile-open'));}
// Query helper for controls that may repeat.
function $(s,root=document){return root.querySelector(s)}
function setMode(mode){if(!['local','cloud'].includes(mode)||state.mode===mode)return;state.mode=mode;localStorage.setItem('compyde-mode',mode);document.querySelectorAll('[data-mode]').forEach(button=>button.classList.toggle('selected',button.dataset.mode===mode));const indicator=$('.mode-indicator');if(indicator)indicator.innerHTML=`<i></i>${mode==='local'?'Local AI':'Cloud AI'}`;const picker=$('[data-mode-menu]');if(picker)picker.innerHTML=`<span class="mode-dot ${mode}"></span>${mode==='local'?'Local AI':'Cloud AI'} <span class="select-chevron">⌄</span>`;const capability=$('.capability-line>span');if(capability)capability.textContent=mode==='local'?'Private inference on this device':'Gemini API · direct from your browser';const caption=$('.privacy-caption');if(caption)caption.innerHTML=`${mode==='local'?'Local mode never sends your prompt to Gemini.':'Your prompts and attachments go directly to Google Gemini.'} <span>AI can make mistakes.</span>`;const localSettings=$('#local-settings'),cloudSettings=$('#cloud-settings');if(localSettings)localSettings.hidden=mode!=='local';if(cloudSettings)cloudSettings.hidden=mode!=='cloud'}
const conversations=[];state.conversations=conversations;
function newChat(){const chat={id:crypto.randomUUID(),title:'New conversation',messages:[],updated:Date.now()};conversations.unshift(chat);state.chatId=chat.id;saveChats();renderMessages();enhanceAssistantActions();renderHistory();$('#chat-input')?.focus()}
function currentChat(){if(!state.chatId){state.chatId=crypto.randomUUID();conversations.unshift({id:state.chatId,title:'New conversation',messages:[],updated:Date.now()})}return conversations.find(c=>c.id===state.chatId)}
let chatDb;
function openChatDb(){if(chatDb)return chatDb;chatDb=new Promise((resolve,reject)=>{const req=indexedDB.open('compyde-local',1);req.onupgradeneeded=()=>req.result.createObjectStore('chats',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return chatDb}
async function saveChats(){try{const db=await openChatDb(),tx=db.transaction('chats','readwrite'),store=tx.objectStore('chats');store.clear();for(const c of conversations)store.put(c)}catch(error){console.error('Could not save conversations locally',error)}}
async function loadChats(){try{const db=await openChatDb(),tx=db.transaction('chats','readonly'),req=tx.objectStore('chats').getAll();const saved=await new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});conversations.push(...saved);if(!saved.length){const migrated=JSON.parse(localStorage.getItem('compyde-chats')||'[]');conversations.push(...migrated);if(migrated.length){await saveChats();localStorage.removeItem('compyde-chats')}}}catch(error){console.error('Could not load local conversations',error)}}
function renderHistory(){const host=$('#history-list');if(!host)return;const q=$('#search-chats')?.value.toLowerCase()||'';host.innerHTML=conversations.filter(c=>String(c.title||'').toLowerCase().includes(q)).map(c=>`<div class="history-item ${c.id===state.chatId?'current':''}"><button class="history-open" data-chat-id="${esc(c.id)}">${icon('file',14)}<span>${esc(c.title)}</span></button><button class="history-delete" data-delete-chat="${esc(c.id)}" aria-label="Delete conversation">×</button></div>`).join('')||'<p class="empty-history">Your conversations will appear here.</p>';host.querySelectorAll('[data-chat-id]').forEach(b=>b.onclick=()=>{state.chatId=b.dataset.chatId;renderMessages();enhanceAssistantActions();renderHistory()});host.querySelectorAll('[data-delete-chat]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteChat,i=conversations.findIndex(c=>c.id===id);if(i>=0)conversations.splice(i,1);if(state.chatId===id)state.chatId=null;saveChats();renderHistory();renderMessages()})}
function exportChats(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(conversations,null,2)],{type:'application/json'}));a.download='compyde-conversations.json';a.click();URL.revokeObjectURL(a.href)}
function enhanceAssistantActions(){const c=conversations.find(x=>x.id===state.chatId);if(!c)return;const nodes=$$('#chat-content .message.user');let n=0;for(let i=0;i<c.messages.length;i++)if(c.messages[i].role==='user'){const node=nodes[n++];if(!node||node.querySelector('[data-edit-message]'))continue;let actions=node.querySelector('.message-actions');if(!actions){actions=document.createElement('div');actions.className='message-actions';node.querySelector('.message-body').append(actions)}const b=document.createElement('button');b.dataset.editMessage=String(i);b.textContent='Edit';b.onclick=()=>{const input=$('#chat-input');input.value=c.messages[i].content;c.messages.splice(i);saveChats();renderMessages();enhanceAssistantActions();input.focus()};actions.append(b)}}
function $$(s,r=document){return [...r.querySelectorAll(s)]}
function renderMessages(){const host=$('#chat-content');if(!host)return;const chat=conversations.find(c=>c.id===state.chatId);if(!chat||!chat.messages.length){host.innerHTML='<div class="chat-welcome"><div class="welcome-mark">'+icon('spark',24)+'</div><div class="section-eyebrow">A LITTLE HELP GOES A LONG WAY</div><h1>What are you<br><span>working on?</span></h1><p>Ask a question, share code or bring a tricky problem.<br>We’ll work through it together.</p><div class="welcome-prompts">'+['Explain recursion simply','Debug my code','Create a study plan for DSA','Solve this programming question'].map(p=>'<button data-chat-suggest="'+esc(p)+'">'+esc(p)+' '+icon('arrow',13)+'</button>').join('')+'</div></div>';host.querySelectorAll('[data-chat-suggest]').forEach(b=>b.onclick=()=>{const input=$('#chat-input');if(input)input.value=b.dataset.chatSuggest;sendPrompt(b.dataset.chatSuggest)});return}host.innerHTML=chat.messages.map((m,i)=>'<article class="message '+m.role+'"><div class="avatar '+(m.role==='assistant'?'bot':'')+'">'+(m.role==='assistant'?icon('spark',15):'Y')+'</div><div class="message-body"><div class="message-label">'+(m.role==='assistant'?'COMPYDE':'YOU')+'</div><div class="message-text">'+formatMessage(m.content)+'</div>'+(m.role==='assistant'?'<div class="message-actions"><button data-copy-message="'+i+'">'+icon('copy',13)+' Copy</button><button data-regenerate>'+icon('spark',13)+' Regenerate</button></div>':'')+'</div></article>').join('');bindCodeCopy(host);host.querySelectorAll('[data-copy-message]').forEach(b=>b.onclick=()=>navigator.clipboard?.writeText(chat.messages[+b.dataset.copyMessage].content));host.querySelectorAll('[data-regenerate]').forEach(b=>b.onclick=()=>regenerate());$('#chat-scroll').scrollTop=$('#chat-scroll').scrollHeight}
function formatMessage(s=''){return esc(s).replace(/\x60{3}(\w*)\n([\s\S]*?)\x60{3}/g,'<pre class="code-block"><code>$2</code><button class="copy-code" data-copy-code>Copy code</button></pre>').replace(/\u0060([^\u0060]+)\u0060/g,'<code>$1</code>').replace(/\n/g,'<br>')}
function bindCodeCopy(container){container?.querySelectorAll('[data-copy-code]').forEach(button=>{button.onclick=()=>navigator.clipboard?.writeText(button.previousElementSibling?.textContent||'')})}function renderAttachments(){const host=$('#attachment-strip');if(!host)return;host.innerHTML=state.attachments.map((a,i)=>'<div class="attachment-chip file-chip">'+icon('file',14)+' <span>'+esc(a.name)+'</span><button data-remove-file="'+i+'" aria-label="Remove '+esc(a.name)+'">'+icon('close',13)+'</button>'+(a.ocr!==undefined?'<textarea data-ocr="'+i+'" aria-label="Edit OCR text from '+esc(a.name)+'" placeholder="Extracted text will appear here">'+esc(a.ocr)+'</textarea>':'')+'</div>').join('');host.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{state.attachments.splice(+b.dataset.removeFile,1);renderAttachments()});host.querySelectorAll('[data-ocr]').forEach(t=>t.oninput=()=>{state.attachments[+t.dataset.ocr].ocr=t.value})}async function handleFiles(e){for(const f of e.target.files){if(f.size>12*1024*1024){alert(`${f.name} is over the 12 MB limit.`);continue}if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(f.type)){alert('Choose a PDF, JPG, PNG or WEBP file.');continue}const item={name:f.name,type:f.type,size:f.size,data:await fileToData(f)};if(f.type.startsWith('image/')&&state.mode==='local'){item.ocr='Extracting text locally…';state.attachments.push(item);renderAttachments();try{item.ocr=await ocrText(item.data)}catch{item.ocr='OCR could not read this image. You can type the visible text here.'}}else state.attachments.push(item)}renderAttachments();e.target.value=''}
let tesseractModule;
async function ocrText(image){if(!tesseractModule)tesseractModule=import(/* @vite-ignore */ 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.esm.min.js');const {createWorker}=await tesseractModule;if(!state.ocrWorker)state.ocrWorker=await createWorker('eng',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.1',langPath:'https://tessdata.projectnaptha.com/4.0.0'});const result=await state.ocrWorker.recognize(image);return result.data.text.trim()||'No text detected. You can type the visible text here.'}
function fileToData(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
async function sendPrompt(prompt){
 if(!prompt||state.generationController)return;
 const chat=currentChat(),mode=state.mode,controller=new AbortController();
 chat.messages.push({role:'user',content:prompt,mode});
 if(chat.messages.length===1)chat.title=prompt.slice(0,44);
 chat.updated=Date.now();
 const files=[...state.attachments];state.attachments=[];saveChats();
 const input=$('#chat-input');if(input)input.value='';
 renderAttachments();renderHistory();
 chat.messages.push({role:'assistant',content:'',mode});
 const idx=chat.messages.length-1;
 renderMessages();enhanceAssistantActions();state.generationController=controller;updateSendButton();
 try{
  let full='';
  const onChunk=t=>{full+=t;chat.messages[idx].content=full;if(state.page==='assistant'&&state.chatId===chat.id){const msg=$('#chat-content .message:last-child .message-text');if(msg){msg.innerHTML=formatMessage(full);bindCodeCopy(msg)}$('#chat-scroll').scrollTop=$('#chat-scroll').scrollHeight}};
  if(mode==='local')await localReply(chat,files,onChunk);else await cloudReply(chat,files,onChunk,controller.signal);
  chat.messages[idx].content=full||'No response text was returned.';
 }catch(err){chat.messages[idx].content=err.name==='AbortError'?'Generation stopped.':`I couldn’t complete that request. ${err.message}\n\n${mode==='cloud'?'Check the Gemini key, network connection, and Google AI Studio quota.':'Check WebGPU support and try a smaller model in Settings.'}`}
 if(state.generationController===controller)state.generationController=null;
 saveChats();
 if(state.page==='assistant'&&state.chatId===chat.id){renderMessages();enhanceAssistantActions()}
 updateSendButton();
}
function updateSendButton(){const send=$('[data-chat-send]');if(!send)return;const running=Boolean(state.generationController),input=$('#chat-input');send.innerHTML=running?'■':icon('send',17);send.setAttribute('aria-label',running?'Stop generation':'Send message');send.title=running?'Stop generation':'';send.classList.toggle('is-stopping',running);if(input){input.disabled=running;input.placeholder=running?'Generating response…':'Message COMPYDE…'}}function stopGeneration(){state.generationController?.abort();state.worker?.postMessage({type:'stop'})}
function regenerate(){const c=conversations.find(c=>c.id===state.chatId);if(!c||c.messages.at(-1)?.role!=='assistant')return;const last=c.messages.pop();const prompt=c.messages.pop();if(prompt?.role==='user'){saveChats();sendPrompt(prompt.content)}else c.messages.push(last)}
async function localReply(chat,files,onChunk){if(!('gpu'in navigator))throw Error('WebGPU is unavailable in this browser. Use a supported desktop browser and device, or select Cloud AI manually.');if(!state.localReady)await loadModel();let last=chat.messages.slice(0,-2).filter(m=>m.role==='user'||m.role==='assistant');let content=chat.messages.at(-2)?.content||'';if(files.length){let extra='';for(const f of files){if(f.type==='application/pdf')extra+=`\n\n[PDF ${f.name}]\n${await extractPdf(f.data)}`;else extra+=`\n\n[Image ${f.name}; edit the locally extracted OCR text above if needed]\n${f.ocr||''}`}content+=extra}last=[...last,{role:'user',content}];const id=crypto.randomUUID();await workerRequest({type:'generate',id,messages:last},onChunk)}
async function cloudReply(chat,files,onChunk,signal){
const messages=chat.messages.filter(m=>['user','assistant'].includes(m.role)).slice(0,-1);
let contents=messages.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]}));
const attached=files.map(f=>f.type==='application/pdf'?extractPdf(f.data).then(text=>({text:'PDF '+f.name+' extracted text:\n'+text})):Promise.resolve({inlineData:{mimeType:f.type,data:f.data.split(',')[1]}}));
const extra=await Promise.all(attached);if(extra.length&&contents.length)contents[contents.length-1].parts.push(...extra);
await streamGemini({apiKey:geminiApiKey,model:DEFAULT_GEMINI_MODEL,contents,onText:onChunk,signal})}
