function openSettings(){const d=$('#settings-dialog');if(!d)return;d.innerHTML=`<div class="settings-form"><div class="dialog-head"><div><span class="section-eyebrow">YOUR AI, YOUR WAY</span><h2>Assistant settings</h2></div><button type="button" class="icon-btn" data-close-settings aria-label="Close">${icon('close')}</button></div><div class="setting-row"><div><b>AI mode</b><small>Switch modes anytime. Your conversation stays here.</small></div><div class="mode-switch"><button type="button" data-setting-mode="local" class="${state.mode==='local'?'selected':''}">Local</button><button type="button" data-setting-mode="cloud" class="${state.mode==='cloud'?'selected':''}">Cloud</button></div></div><div class="setting-panel" id="local-settings" ${state.mode==='local'?'':'hidden'}><h3>Local AI model</h3><p>Models run with WebGPU in your browser. Initial download retrieves model files from the MLC model host. Model cache can use several GB of storage.</p><select id="model-select">${models.map(m=>`<option value="${m.id}" ${m.id===state.model?'selected':''}>${m.name} · ${m.size}</option>`).join('')}</select><p class="model-desc">${models.find(m=>m.id===state.model)?.desc}</p><div class="hardware-status">${'gpu'in navigator?'✓ WebGPU is available in this browser':'! WebGPU not detected — local inference cannot start'}</div>${state.loading?'<progress id="model-progress" max="1" value="0"></progress><small>Downloading / initializing…</small>':''}<div class="settings-buttons"><button type="button" class="primary-btn" data-load-model>${state.localReady?'Model ready':'Download & load model'}</button>${state.localReady?'<button type="button" class="outline-btn" data-unload>Unload</button>':''}</div><button type="button" class="outline-btn" data-delete-model>Delete cached model files</button><div class="privacy-box">Prompts in Local AI are processed on this device and are never sent to Gemini.</div></div><div class="setting-panel" id="cloud-settings" ${state.mode==='cloud'?'':'hidden'}><h3>Google Gemini</h3><p>Connect directly to the Gemini API. Your key is kept in memory for this tab and sent from your browser to Google. It is not saved to this device.</p><label class="key-label" for="gemini-key">Gemini API key</label><input id="gemini-key" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your rotated Gemini API key"><div class="key-status" id="gemini-key-status">${geminiApiKey?'A key is active for this tab.':'No key connected yet.'}</div><div class="settings-buttons"><span class="tiny-hint">Paste a key above. It becomes active in this tab only.</span><button type="button" class="outline-btn" data-clear-gemini>Forget key</button></div><div class="privacy-box">Direct browser mode does not use Cloudflare. Anyone using your browser can inspect its API requests; use a key restricted to the Gemini API, watch quota and usage, and never publish a key in the site code.</div></div><button class="clear-data" type="button" data-clear-data>Delete all local chats and preferences</button></div>`;d.querySelector('[data-delete-model]')?.addEventListener('click',async()=>{if(!confirm('Delete the cached files for this model from this browser?'))return;if(state.localReady){await workerRequest({type:'unload',id:crypto.randomUUID()});state.localReady=false}const {deleteModelAllInfoInCache}=await import('@mlc-ai/web-llm');await deleteModelAllInfoInCache(state.model);alert('Cached model files deleted.');d.close()});d.showModal();d.querySelector('#gemini-key')?.addEventListener('input',event=>{geminiApiKey=event.currentTarget.value.trim();$('#gemini-key-status',d).textContent=geminiApiKey?'Gemini key active in this tab.':'No key connected yet.'});d.querySelector('[data-clear-gemini]')?.addEventListener('click',()=>{geminiApiKey='';$('#gemini-key',d).value='';$('#gemini-key-status',d).textContent='Key forgotten.'});d.querySelectorAll('[data-setting-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.settingMode);d.close()});$('#model-select',d).onchange=e=>{state.model=e.target.value;localStorage.setItem('compyde-model',state.model)};$('[data-load-model]',d).onclick=()=>{if(!('gpu'in navigator)){alert('WebGPU is unavailable. Try a supported Chromium browser with WebGPU enabled.');return}state.model=$('#model-select',d).value;localStorage.setItem('compyde-model',state.model);loadModel().catch(e=>alert(`Could not load model: ${e.message}`))};$('[data-unload]',d)?.addEventListener('click',()=>{const id=crypto.randomUUID();state.worker?.postMessage({type:'unload',id});state.localReady=false;d.close()});$('[data-clear-data]',d).onclick=()=>{if(confirm('Delete all local conversations and preferences?')){localStorage.clear();conversations.splice(0);d.close();render()}}}
