async function extractPdf(data){const pdfjs=await import('pdfjs-dist');pdfjs.GlobalWorkerOptions.workerSrc=new URL('pdfjs-dist/build/pdf.worker.min.mjs',import.meta.url).toString();const raw=Uint8Array.from(atob(data.split(',')[1]),c=>c.charCodeAt(0));const doc=await pdfjs.getDocument({data:raw}).promise;let text='';for(let i=1;i<=Math.min(doc.numPages,20);i++){const page=await doc.getPage(i);const content=await page.getTextContent();text+=content.items.map(x=>x.str).join(' ')+'\n'}if(text.trim().length>20)return text.slice(0,50000);let scanned='';for(let i=1;i<=Math.min(doc.numPages,3);i++){const page=await doc.getPage(i),viewport=page.getViewport({scale:1.5}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvas,viewport}).promise;scanned+=`\n[Scanned page ${i}]\n${await ocrText(canvas)}`}return scanned.trim()?`OCR extracted only the first ${Math.min(doc.numPages,3)} scanned pages.\n${scanned}`:'No readable text was found in this PDF.'}
