function adaptJavaEntry(code){const match=code.match(/\b(?:public\s+)?class\s+([A-Za-z_$][\w$]*)/);if(!match||match[1]==="prog")return code;const name=match[1];return code.replace(new RegExp("\\b(?:public\\s+)?class\\s+"+name+"\\b"),"class prog").replace(new RegExp("\\bnew\\s+"+name+"\\b",'g'),"new prog").replace(new RegExp("\\b"+name+"(?=\\s*\\()",'g'),"prog").replace(new RegExp("\\b"+name+"(?=\\s*\\.)",'g'),"prog")}
